def catalog_code_for_item(item: ET.Element) -> str | None:
    """Match model or variant IDs on hyphen boundaries; prefer item_group_id."""
    ns = {"g": "http://base.google.com/ns/1.0"}
    for tag in ("g:item_group_id", "item_group_id", "g:id", "id"):
        candidate = text_of(item, tag, ns if tag.startswith("g:") else None).strip().upper()
        if candidate in CATALOG_PRODUCT_CODES:
            return candidate
        for code in _CATALOG_CODES_LONGEST_FIRST:
            if candidate.startswith(code + "-"):
                return code
    return None


def catalog_image_gallery(item: ET.Element) -> tuple[str, list[str]]:
    """First image stays image_link. Count each distinct image URL once."""
    ns = {"g": "http://base.google.com/ns/1.0"}
    primary = text_of(item, "g:image_link", ns) or text_of(item, "image_link")
    if not primary:
        return "", []
    urls = [primary]
    urls.extend((child.text or "").strip() for child in item
                if child.tag.rsplit("}", 1)[-1] == "additional_image_link")
    gallery, seen = [], set()
    for url in urls:
        if not url:
            continue
        key = _clean_url(url)
        if key not in seen:
            gallery.append(url)
            seen.add(key)
    return primary, gallery




