def _matches_product_code(product_id: str, codes: set[str]) -> bool:
    normalized = (product_id or "").strip().upper()

    return any(
        normalized == code
        or normalized.startswith(code + "-")
        for code in codes
    )


def get_variant_class(product_id: str) -> str:
    return "variant-catalog"


