# -------------------------
# XML utilities
# -------------------------

def text_of(
    item: ET.Element,
    tag: str,
    ns: dict | None = None,
) -> str:

    if ns and ":" in tag:
        return (
            item.findtext(
                tag,
                default="",
                namespaces=ns,
            )
            or ""
        ).strip()

    return (item.findtext(tag, default="") or "").strip()


def set_image_link(item: ET.Element, new_url: str):

    ns = {"g": "http://base.google.com/ns/1.0"}

    img = item.find("g:image_link", ns)

    if img is not None:
        img.text = new_url

        for extra in item.findall("g:additional_image_link", ns):
            item.remove(extra)

        return

    img = item.find("image_link")

    if img is not None:
        img.text = new_url

        for extra in item.findall("additional_image_link"):
            item.remove(extra)

        return

    ET.SubElement(item, "image_link").text = new_url


def extract_title(
    item: ET.Element,
    ns: dict | None = None,
) -> str:

    candidates = [
        text_of(item, "title", ns),
        text_of(item, "g:title", ns),
        text_of(item, "name", ns),
        text_of(item, "product_name", ns),
        text_of(item, "product_title", ns),
        text_of(item, "item_name", ns),
        text_of(item, "description", ns),
        text_of(item, "g:description", ns),
    ]

    for c in candidates:
        if c:
            return " ".join(c.split()).strip()

    return ""


def get_custom_labels(
    item: ET.Element,
    ns: dict | None = None,
) -> str:

    labels = []

    for i in range(5):
        labels.append(text_of(item, f"g:custom_label_{i}", ns))
        labels.append(text_of(item, f"custom_label_{i}", ns))

    return " ".join([x for x in labels if x]).lower()


# -------------------------
# Image selection
# -------------------------

def choose_images_any(item: ET.Element):

    ns = {"g": "http://base.google.com/ns/1.0"}

    primary_raw = (
        text_of(item, "g:image_link", ns=ns)
        or text_of(item, "image_link")
    )

    additional_raw = []

    for e in item.findall(
        "g:additional_image_link",
        namespaces=ns,
    ):
        if e is not None and (e.text or "").strip():
            additional_raw.append((e.text or "").strip())

    for e in item.findall("additional_image_link"):
        if e is not None and (e.text or "").strip():
            additional_raw.append((e.text or "").strip())

    all_urls = [primary_raw] + additional_raw

    seen = set()
    uniq = []

    for u in all_urls:
        cu = _clean_url(u)

        if cu and cu not in seen:
            seen.add(cu)
            uniq.append(u)

    primary = uniq[0] if uniq else primary_raw
    s1 = uniq[1] if len(uniq) > 1 else primary

    return primary, s1


# -------------------------
# HTTP -> Data URI
# -------------------------

_TRANSPARENT_PNG = base64.b64decode(
    "iVBORw0KGgoAAAANSUhEUgAAAAEAAAABCAQAAAC1HAwCAAAAC0lEQVR4nGMAAQAABQABDQottAAAAABJRU5ErkJggg=="
)


def _transparent_data_uri() -> str:
    return (
        "data:image/png;base64,"
        + base64.b64encode(_TRANSPARENT_PNG).decode("ascii")
    )


def _guess_mime(
    url: str,
    content_type: str | None,
) -> str:

    if content_type and "image/" in content_type:
        return content_type.split(";")[0].strip()

    u = (url or "").lower()

    if ".png" in u:
        return "image/png"

    if ".webp" in u:
        return "image/webp"

    if ".svg" in u:
        return "image/svg+xml"

    return "image/jpeg"


def _is_kaya_url(url: str) -> bool:
    hostname = (urlsplit(url).hostname or "").lower()

    return (
        hostname == "kayakirtasiye.com.tr"
        or hostname.endswith(".kayakirtasiye.com.tr")
    )


def _is_vatkali_url(url: str) -> bool:
    hostname = (urlsplit(url).hostname or "").lower()

    return (
        hostname == "vatkali.com"
        or hostname.endswith(".vatkali.com")
    )


async def fetch_kaya_with_browser(url: str) -> str:
    """
    Kayak görselleri Railway/httpx isteğine 403 verirse,
    aynı görseli gerçek Chromium context'i üzerinden çekmeyi dener.
    """

    global _browser

    await _ensure_browser()

    context = None

    try:
        context = await _browser.new_context(
            user_agent=(
                "Mozilla/5.0 (Windows NT 10.0; Win64; x64) "
                "AppleWebKit/537.36 (KHTML, like Gecko) "
                "Chrome/126.0 Safari/537.36"
            ),
            locale="tr-TR",
            extra_http_headers={
                "Accept": (
                    "image/avif,"
                    "image/webp,"
                    "image/apng,"
                    "image/*,"
                    "*/*;q=0.8"
                ),
                "Accept-Language": "tr-TR,tr;q=0.9,en;q=0.8",
                "Referer": "https://www.kayakirtasiye.com.tr/",
            },
        )

        response = await context.request.get(
            url,
            timeout=30000,
        )

        if not response.ok:
            print(
                "KAYA_BROWSER_FETCH_FAILED:",
                url,
                "status=",
                response.status,
            )
            return url

        body = await response.body()
        headers = await response.all_headers()

        content_type = (
            headers.get("content-type")
            or ""
        ).lower()

        if "image/" not in content_type:
            print(
                "KAYA_BROWSER_NOT_IMAGE:",
                url,
                "content-type=",
                content_type,
            )
            return url

        if len(body) > 8_000_000:
            print(
                "KAYA_BROWSER_IMAGE_TOO_LARGE:",
                url,
                len(body),
            )
            return url

        mime = _guess_mime(
            url,
            content_type,
        )

        b64 = base64.b64encode(body).decode("ascii")

        print(
            "KAYA_BROWSER_FETCH_OK:",
            url,
            "bytes=",
            len(body),
        )

        return f"data:{mime};base64,{b64}"

    except Exception as e:
        print(
            "KAYA_BROWSER_FETCH_EXCEPTION:",
            url,
            repr(e),
        )

        return url

    finally:
        if context is not None:
            try:
                await context.close()
            except Exception:
                pass


async def to_data_uri(
    url: str,
    client: httpx.AsyncClient,
) -> str:

    if not url:
        return _transparent_data_uri()

    if url.startswith("data:"):
        return url

    cleaned_url = _clean_url(url)

    headers = {
        "User-Agent": (
            "Mozilla/5.0 (Windows NT 10.0; Win64; x64) "
            "AppleWebKit/537.36 (KHTML, like Gecko) "
            "Chrome/126.0 Safari/537.36"
        ),
        "Accept": (
            "image/avif,"
            "image/webp,"
            "image/apng,"
            "image/*,"
            "*/*;q=0.8"
        ),
        "Accept-Language": "tr-TR,tr;q=0.9,en;q=0.8",
    }

    if _is_kaya_url(cleaned_url):
        headers["Referer"] = "https://www.kayakirtasiye.com.tr/"

    elif _is_vatkali_url(cleaned_url):
        headers["Referer"] = "https://www.vatkali.com/"

    try:
        r = await client.get(
            cleaned_url,
            headers=headers,
            timeout=30.0,
            follow_redirects=True,
        )

        # Kaya httpx tarafında 403 verirse
        # doğrudan Chromium fallback'e geç.
        if _is_kaya_url(cleaned_url) and r.status_code == 403:

            print(
                "KAYA_HTTPX_403_BROWSER_RETRY:",
                cleaned_url,
            )

            return await fetch_kaya_with_browser(
                cleaned_url
            )

        r.raise_for_status()

        ct = (
            r.headers.get("content-type")
            or ""
        ).lower()

        if "image/" not in ct:

            print(
                "IMAGE_NOT_IMAGE:",
                cleaned_url,
                "status=",
                r.status_code,
                "content-type=",
                r.headers.get("content-type"),
            )

            # Kaya ise Chromium ile bir kez daha dene.
            if _is_kaya_url(cleaned_url):
                return await fetch_kaya_with_browser(
                    cleaned_url
                )

            return cleaned_url

        if len(r.content) > 8_000_000:

            print(
                "IMAGE_TOO_LARGE:",
                cleaned_url,
                len(r.content),
            )

            return cleaned_url

        mime = _guess_mime(
            cleaned_url,
            r.headers.get("content-type"),
        )

        b64 = base64.b64encode(
            r.content
        ).decode("ascii")

        return f"data:{mime};base64,{b64}"

    except Exception as e:

        print(
            "IMAGE_FETCH_FAILED:",
            cleaned_url,
            repr(e),
        )

        # Kaya için httpx exception oluştuysa
        # Chromium ile son bir deneme.
        if _is_kaya_url(cleaned_url):

            print(
                "KAYA_EXCEPTION_BROWSER_RETRY:",
                cleaned_url,
            )

            return await fetch_kaya_with_browser(
                cleaned_url
            )

        return cleaned_url


# -------------------------
# Playwright
# -------------------------

_pw = None
_browser = None
_pw_lock = asyncio.Lock()


def _is_fatal_playwright_error(e: Exception) -> bool:

    msg = str(e).lower()

    return any(
        s in msg
        for s in [
            "targetclosederror",
            "target page",
            "has been closed",
            "writeunixtransport closed",
            "handler is closed",
            "playwright connection closed",
        ]
    )


async def _restart_playwright():

    global _pw, _browser

    try:
        if _browser:
            await _browser.close()
    except Exception:
        pass

    _browser = None

    try:
        if _pw:
            await _pw.stop()
    except Exception:
        pass

    _pw = None

    _pw = await async_playwright().start()

    _browser = await _pw.chromium.launch(
        headless=True,
        args=[
            "--no-sandbox",
            "--disable-setuid-sandbox",
            "--disable-dev-shm-usage",
            "--no-zygote",
            "--disable-gpu",
        ],
    )


async def _ensure_browser():

    global _pw, _browser

    async with _pw_lock:

        try:
            if _pw is None:
                _pw = await async_playwright().start()

            if (
                _browser is None
                or (
                    hasattr(_browser, "is_connected")
                    and not _browser.is_connected()
                )
            ):

                try:
                    if _browser:
                        await _browser.close()
                except Exception:
                    pass

                _browser = await _pw.chromium.launch(
                    headless=True,
                    args=[
                        "--no-sandbox",
                        "--disable-setuid-sandbox",
                        "--disable-dev-shm-usage",
                        "--no-zygote",
                        "--disable-gpu",
                    ],
                )

        except Exception as e:

            if _is_fatal_playwright_error(e):
                await _restart_playwright()
            else:
                raise


@app.on_event("startup")
async def _startup():
    await _ensure_browser()


@app.on_event("shutdown")
async def _shutdown():

    global _pw, _browser

    try:
        if _browser:
            await _browser.close()
    except Exception:
        pass

    _browser = None

    try:
        if _pw:
            await _pw.stop()
    except Exception:
        pass

    _pw = None


async def render_png(
    html: str,
    width=1080,
    height=1080,
) -> bytes:

    global _browser

    async with _render_sem:

        await _ensure_browser()

        async def _do() -> bytes:

            page = await _browser.new_page(
                viewport={
                    "width": width,
                    "height": height,
                }
            )

            try:

                await page.set_content(
                    html,
                    wait_until="networkidle",
                    timeout=15000,
                )

                await page.evaluate("() => document.fonts.ready")
                if 'data-renderReady' in html or 'dataset.renderReady' in html:
                    await page.wait_for_function(
                        "document.documentElement.dataset.renderReady === 'true'",
                        timeout=10000,
                    )

                await page.wait_for_timeout(300)

                frame = page.locator(".frame")

                await frame.wait_for(
                    state="visible",
                    timeout=5000,
                )

                return await frame.screenshot(
                    type="png"
                )

            finally:

                try:
                    await page.close()
                except Exception:
                    pass

        try:
            return await _do()

        except Exception as e:

            if _is_fatal_playwright_error(e):

                await _restart_playwright()

                return await _do()

            raise


