@app.get("/render.png")
async def render_endpoint(
    request: Request,
    product_id: str = Query(""),
    title: str = Query(""),
    price: str = Query(""),
    sale_price: str = Query(""),
    product_image_primary: str = Query(""),
    product_image_secondary_1: str = Query(""),
    logo_url: str = Query(""),
    design: str = Query("meta_v1"),
    w: int = Query(1080),
    h: int = Query(1080),
    fv: str = Query(""),
):

    fv = FRAME_VERSION + "-" + fv
    variant_class = get_variant_class(product_id)

    # Feed fiyatı nihaidir; ek kampanya indirimi hesaplanmaz.
    price = format_feed_tl(price)
    sale_price = format_feed_tl(sale_price)
    campaign_price = sale_price or price

    old_hidden, new_hidden, single_hidden = hidden_flags(
        price,
        sale_price,
    )


    template_path, css_path = get_template_and_css(
        design
    )

    with open(
        template_path,
        "r",
        encoding="utf-8",
    ) as f:
        tpl = f.read()

    with open(
        css_path,
        "r",
        encoding="utf-8",
    ) as f:
        css = f.read()

    base_url = get_base_url(request)

    white_logo_url = (
        f"{base_url}/static/"
        "vatkalilogo-beyaz.png"
    )

    if not logo_url:

        if design == "kaya_meta_v1":

            logo_url = (
                f"{base_url}/static/"
                "kayakirtasiyelogo.png"
            )

        else:

            logo_url = (
                f"{base_url}/static/"
                "vatkalilogo.svg"
            )

    background_url = (
        f"{base_url}/static/"
        "background_summer26.png"
    )

    # Both current Vatkali layouts use only the feed's primary image.
    if design in {"meta_v1", "tiktok_v1"}:
        product_image_secondary_1 = ""

    secondary_for_cache = (
        product_image_secondary_1
        if design == "meta_v1"
        else ""
    )

    cache_key = build_render_cache_key(
        product_id=product_id,
        title=title,
        price=price,
        sale_price=sale_price,
        product_image_primary=product_image_primary,
        product_image_secondary_1=secondary_for_cache,
        logo_url=logo_url,
        design=(
            f"{design}_{variant_class}_"
            f"catalog40_{fv}"
        ),
        w=w,
        h=h,
    )

    cache_file = get_cache_file_path(
        cache_key
    )

    if os.path.exists(cache_file):

        with open(
            cache_file,
            "rb",
        ) as f:
            png = f.read()

        headers = {
            "Cache-Control":
            "public, max-age=31536000, immutable"
        }

        return Response(
            content=png,
            media_type="image/png",
            headers=headers,
        )

    async with httpx.AsyncClient(
        follow_redirects=True
    ) as client:

        if design in {"meta_v1", "tiktok_v1"}:
            # Current layouts embed their logo and have no background asset.
            # Fetch only the product photo; do not call our public service for assets.
            product_image_primary_data = await to_data_uri(
                product_image_primary, client,
            )
            product_image_secondary_1_data = ""
            logo_data = ""
            white_logo_data = ""
            background_data = ""

        elif design == "meta_v1":

            (
                product_image_primary_data,
                product_image_secondary_1_data,
                logo_data,
                white_logo_data,
                background_data,
            ) = await asyncio.gather(

                to_data_uri(
                    product_image_primary,
                    client,
                ),

                to_data_uri(
                    product_image_secondary_1,
                    client,
                ),

                to_data_uri(
                    logo_url,
                    client,
                ),

                to_data_uri(
                    white_logo_url,
                    client,
                ),

                to_data_uri(
                    background_url,
                    client,
                ),
            )

        else:

            (
                product_image_primary_data,
                logo_data,
                white_logo_data,
                background_data,
            ) = await asyncio.gather(

                to_data_uri(
                    product_image_primary,
                    client,
                ),

                to_data_uri(
                    logo_url,
                    client,
                ),

                to_data_uri(
                    white_logo_url,
                    client,
                ),

                to_data_uri(
                    background_url,
                    client,
                ),
            )

            product_image_secondary_1_data = ""

    css = css.replace("{{FONT_CSS}}", FONT_CSS)
    html = tpl.replace(
        "{{CSS}}",
        css,
    )
    if design in {"meta_v1", "tiktok_v1"}:
        key = "meta" if design == "meta_v1" else "tiktok"
        html = html.replace("{{frame_logo}}", FRAME_LOGOS[key])
        html = html.replace("{{FRAME_SCRIPT}}", FRAME_LAYOUT_SCRIPT)


    html = html.replace(
        "{{product_id}}",
        product_id,
    )

    html = html.replace(
        "{{variant_class}}",
        variant_class,
    )

    html = html.replace(
        "{{product_image_primary}}",
        product_image_primary_data,
    )

    html = html.replace(
        "{{product_image_secondary_1}}",
        product_image_secondary_1_data,
    )

    html = html.replace(
        "{{logo_url}}",
        logo_data,
    )

    html = html.replace(
        "{{white_logo_url}}",
        white_logo_data,
    )

    html = html.replace(
        "{{background_url}}",
        background_data,
    )

    html = html.replace(
        "{{title}}",
        escape(title),
    )

    html = html.replace(
        "{{price}}",
        price,
    )

    html = html.replace(
        "{{sale_price}}",
        sale_price,
    )

    html = html.replace(
        "{{campaign_price}}",
        campaign_price,
    )

    html = html.replace(
        "{{old_hidden}}",
        old_hidden,
    )

    html = html.replace(
        "{{new_hidden}}",
        new_hidden,
    )

    html = html.replace(
        "{{single_hidden}}",
        single_hidden,
    )

    try:

        png = await render_png(
            html,
            width=w,
            height=h,
        )

        with open(
            cache_file,
            "wb",
        ) as f:
            f.write(png)

    except Exception as e:

        print(
            "RENDER_FAILED:",
            repr(e),
        )

        return Response(
            status_code=500
        )

    headers = {
        "Cache-Control":
        "public, max-age=31536000, immutable"
    }

    return Response(
        content=png,
        media_type="image/png",
        headers=headers,
    )


@app.get(
    "/feed_meta.xml",
    response_class=PlainTextResponse,
)
async def feed_meta(request: Request):

    base_url = get_base_url(request)

    fv = (
        request.query_params.get("v")
        or FRAME_VERSION
    ).strip()

    async with httpx.AsyncClient(
        timeout=90
    ) as client:

        r = await client.get(
            FEED_URL_META
        )

        r.raise_for_status()

    root = ET.fromstring(r.text)

    channel = root.find("channel")

    if channel is None:

        return PlainTextResponse(
            r.text,
            media_type="application/xml",
        )

    items = channel.findall("item")

    ns = {
        "g": "http://base.google.com/ns/1.0"
    }

    for item in items:

        product_id = (
            item.findtext(
                "g:id",
                default="",
                namespaces=ns,
            )
            or item.findtext("id")
            or ""
        ).strip()


        catalog_code = catalog_code_for_item(item)
        if catalog_code is None:
            channel.remove(item)
            continue

        title = extract_title(
            item,
            ns,
        )

        price = format_currency_tr(
            item.findtext(
                "g:price",
                default="",
                namespaces=ns,
            )
            or ""
        )

        sale = format_currency_tr(
            item.findtext(
                "g:sale_price",
                default="",
                namespaces=ns,
            )
            or ""
        )

        if not sale:
            sale = price

        primary, _ = catalog_image_gallery(item)
        if not primary:
            channel.remove(item)
            continue
        s1 = ""

        custom_labels = (
            get_custom_labels(
                item,
                ns,
            )
            .replace("`", "'")
            .replace("’", "'")
        )

        if (
            "summer'26" in custom_labels
            or "summer26" in custom_labels
            or "summer 26" in custom_labels
        ):
            design = "meta_v1"
        else:
            design = "meta_v1"

        sig = build_sig(
            product_id,
            design,
            title,
            price,
            sale,
            primary,
            s1,
            fv,
        )

        render_url = (
            f"{base_url}/render.png"
            f"?product_id={quote_plus(product_id)}"
            f"&title={quote_plus(title)}"
            f"&price={quote_plus(price)}"
            f"&sale_price={quote_plus(sale)}"
            f"&product_image_primary={quote_plus(primary)}"
            f"&product_image_secondary_1={quote_plus(s1)}"
            f"&design={quote_plus(design)}"
            f"&w=1080&h=1080"
            f"&fv={quote_plus(fv)}"
            f"&v={sig}"
        )

        set_image_link(
            item,
            render_url,
        )

    xml_out = ET.tostring(
        root,
        encoding="utf-8",
        xml_declaration=True,
    ).decode("utf-8")

    headers = {
        "Cache-Control":
        "no-store, no-cache, must-revalidate, max-age=0"
    }

    return PlainTextResponse(
        xml_out,
        media_type="application/xml",
        headers=headers,
    )


