@app.get("/probe")
async def probe(
    url: str = Query(...),
):

    headers = {
        "User-Agent": (
            "Mozilla/5.0 "
            "(Windows NT 10.0; Win64; x64) "
            "AppleWebKit/537.36 "
            "(KHTML, like Gecko) "
            "Chrome/126.0 Safari/537.36"
        ),
        "Accept": (
            "image/avif,"
            "image/webp,"
            "image/apng,"
            "image/*,"
            "*/*;q=0.8"
        ),
        "Accept-Language":
            "tr-TR,tr;q=0.9,en;q=0.8",
    }

    try:

        async with httpx.AsyncClient(
            follow_redirects=True,
            timeout=20,
            headers=headers,
        ) as client:

            r = await client.get(
                url
            )

            content_type = (
                r.headers.get(
                    "content-type",
                    "",
                )
            )

            is_text = (
                "text" in content_type
                or "html" in content_type
            )

            return {
                "url": url,
                "status_code":
                    r.status_code,
                "content_type":
                    content_type,
                "content_length":
                    len(r.content),
                "first_50_bytes_base64":
                    base64.b64encode(
                        r.content[:50]
                    ).decode("ascii"),
                "text_preview":
                    r.text[:300]
                    if is_text
                    else None,
            }

    except Exception as e:

        return {
            "url": url,
            "error": str(e),
        }

